<?php
declare(strict_types=1);
require_once __DIR__.'/../config/koneksi.php';
const APP_NAME='Datanix';
const APP_ROOT=__DIR__.'/..';
$baseUrl=rtrim(getenv('APP_BASE_URL')?:'','/');
$basePath=(string)(parse_url($baseUrl,PHP_URL_PATH)?:'');
if($basePath===''&&str_starts_with($baseUrl,'/'))$basePath=$baseUrl;
$basePath='/'.trim($basePath,'/');
$cookiePath=$basePath==='/'?'/':$basePath.'/';
$isHttps=((!empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off')||strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))==='https');
session_name('datanix_session');
if(session_status()!==PHP_SESSION_ACTIVE){session_set_cookie_params(['lifetime'=>0,'path'=>$cookiePath,'secure'=>$isHttps,'httponly'=>true,'samesite'=>$isHttps?'None':'Lax']);session_start();}
header('X-Content-Type-Options: nosniff');header('X-Frame-Options: SAMEORIGIN');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');
function url(string $path=''):string{$base=rtrim(getenv('APP_BASE_URL')?:'','/');return $base.'/'.ltrim($path,'/');}
function e(mixed $value):string{return htmlspecialchars((string)($value??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function redirect(string $path):never{header('Location: '.(preg_match('~^https?://~i',$path)?$path:url($path)),true,303);exit;}
function csrf_token():string{if(empty($_SESSION['_csrf']))$_SESSION['_csrf']=bin2hex(random_bytes(32));return (string)$_SESSION['_csrf'];}
function csrf_field():string{return '<input type="hidden" name="csrf_token" value="'.e(csrf_token()).'">';}
function verify_csrf():void{$sent=(string)($_POST['csrf_token']??$_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!hash_equals(csrf_token(),$sent)){http_response_code(419);if(str_contains(strtolower((string)($_SERVER['HTTP_ACCEPT']??'')),'application/json'))json_response(['ok'=>false,'error'=>'Sesi keamanan kedaluwarsa. Muat ulang halaman.'],419);exit('Sesi keamanan kedaluwarsa. Muat ulang halaman.');}}
function json_response(array $body,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function request_data():array{$type=strtolower((string)($_SERVER['CONTENT_TYPE']??''));if(str_contains($type,'application/json')){$raw=file_get_contents('php://input')?:'';$data=json_decode($raw,true);return is_array($data)?$data:[];}return $_POST;}
function flash(string $type,string $message):void{$_SESSION['_flash'][]=['type'=>$type,'message'=>$message];}
function consume_flash():array{$items=$_SESSION['_flash']??[];unset($_SESSION['_flash']);return is_array($items)?$items:[];}
function current_user():?array{static $checked=false,$user=null;if($checked)return $user;$checked=true;$id=(int)($_SESSION['user_id']??0);if($id<1)return null;$st=$GLOBALS['pdo']->prepare('SELECT id,name,email,role,is_active,ai_disclosure_at,last_login_at,created_at FROM users WHERE id=? LIMIT 1');$st->execute([$id]);$user=$st->fetch()?:null;if(!$user||(int)$user['is_active']!==1){$user=null;unset($_SESSION['user_id'],$_SESSION['workspace_id']);}return $user;}
function require_login():array{$u=current_user();if(!$u){$next=rawurlencode((string)($_SERVER['REQUEST_URI']??''));redirect('login.php?next='.$next);}return $u;}
function require_admin():array{$u=require_login();if($u['role']!=='admin'){http_response_code(403);exit('Akses admin diperlukan.');}return $u;}
function current_workspace():?array{$user=current_user();if(!$user)return null;$id=(int)($_SESSION['workspace_id']??0);$sql='SELECT w.*,wm.member_role FROM workspaces w JOIN workspace_members wm ON wm.workspace_id=w.id WHERE wm.user_id=? AND w.status="active"';$params=[(int)$user['id']];if($id>0){$sql.=' AND w.id=?';$params[]=$id;}$sql.=' LIMIT 1';$st=$GLOBALS['pdo']->prepare($sql);$st->execute($params);$workspace=$st->fetch();if(!$workspace&&$id>0){unset($_SESSION['workspace_id']);return current_workspace();}if(!$workspace&&$id===0){$st=$GLOBALS['pdo']->prepare('SELECT w.*,wm.member_role FROM workspaces w JOIN workspace_members wm ON wm.workspace_id=w.id WHERE wm.user_id=? AND w.status="active" ORDER BY w.id LIMIT 1');$st->execute([(int)$user['id']]);$workspace=$st->fetch();}if($workspace)$_SESSION['workspace_id']=(int)$workspace['id'];return $workspace?:null;}
function require_workspace():array{require_login();$workspace=current_workspace();if(!$workspace)redirect('workspaces/create.php');return $workspace;}
function workspace_role():string{return (string)(current_workspace()['member_role']??'');}
function can(string $permission,?array $workspace=null):bool{$workspace??=current_workspace();if(!$workspace)return false;$role=(string)$workspace['member_role'];$rules=['view'=>['owner','admin','editor','analyst','viewer'],'ask'=>['owner','admin','editor','analyst'],'edit_data'=>['owner','admin','editor'],'connect'=>['owner','admin'],'build_dashboard'=>['owner','admin','editor','analyst'],'manage_members'=>['owner','admin'],'delete'=>['owner','admin']];return in_array($role,$rules[$permission]??[],true);}
function require_permission(string $permission):array{$w=require_workspace();if(!can($permission,$w)){http_response_code(403);exit('Peran workspace Anda tidak dapat melakukan tindakan ini.');}return $w;}
function plan_limits(?array $workspace=null):array{$plan=(string)($workspace['plan']??'free');return match($plan){'business'=>['workspaces'=>-1,'datasets'=>-1,'queries'=>10000,'advanced'=>true,'builder'=>true,'exports'=>true,'saved_insights'=>true,'members'=>-1,'api'=>true],'pro'=>['workspaces'=>-1,'datasets'=>-1,'queries'=>2000,'advanced'=>true,'builder'=>true,'exports'=>true,'saved_insights'=>true,'members'=>1,'api'=>false],default=>['workspaces'=>1,'datasets'=>3,'queries'=>100,'advanced'=>false,'builder'=>false,'exports'=>false,'saved_insights'=>false,'members'=>1,'api'=>false]};}
function usage_count(string $type,?int $workspaceId=null,?int $userId=null):int{$month=date('Y-m');$conditions=['usage_type=?','month_key=?'];$params=[$type,$month];if($workspaceId){$conditions[]='workspace_id=?';$params[]=$workspaceId;}if($userId){$conditions[]='user_id=?';$params[]=$userId;}$st=$GLOBALS['pdo']->prepare('SELECT COALESCE(SUM(units),0) FROM usage_logs WHERE '.implode(' AND ',$conditions));$st->execute($params);return (int)$st->fetchColumn();}
function audit_log(string $action,?string $entityType=null,?int $entityId=null,array $metadata=[]):void{$u=current_user();$w=current_workspace();$st=$GLOBALS['pdo']->prepare('INSERT INTO audit_logs(workspace_id,actor_id,action,entity_type,entity_id,metadata_json) VALUES(?,?,?,?,?,?)');$st->execute([$w?(int)$w['id']:null,$u?(int)$u['id']:null,$action,$entityType,$entityId,$metadata?json_encode($metadata,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE):null]);}
function slugify(string $text):string{$text=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$text)?:$text;$text=strtolower(preg_replace('/[^A-Za-z0-9]+/','-',trim($text))??'workspace');return trim($text,'-')?:'workspace';}
function encrypt_secret(string $plain):array{$key=(string)(getenv('APP_ENCRYPTION_KEY')?:'');if(strlen($key)===64&&ctype_xdigit($key))$key=hex2bin($key);if(strlen($key)!==32)throw new RuntimeException('APP_ENCRYPTION_KEY harus berisi 32 byte atau 64 karakter hex.');$nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag);if($cipher===false)throw new RuntimeException('Enkripsi secret gagal.');return ['ciphertext'=>base64_encode($cipher),'nonce'=>base64_encode($nonce),'tag'=>base64_encode($tag)];}
function decrypt_secret(?string $ciphertext,?string $nonce,?string $tag):?string{if(!$ciphertext||!$nonce||!$tag)return null;$key=(string)(getenv('APP_ENCRYPTION_KEY')?:'');if(strlen($key)===64&&ctype_xdigit($key))$key=hex2bin($key);if(strlen($key)!==32)return null;$result=openssl_decrypt(base64_decode($ciphertext,true)?:'','aes-256-gcm',$key,OPENSSL_RAW_DATA,base64_decode($nonce,true)?:'',base64_decode($tag,true)?:'');return $result===false?null:$result;}
function connector_public_ips(string $host):array{$host=strtolower(trim($host,'[] .'));if(filter_var($host,FILTER_VALIDATE_IP))return filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)!==false?[$host]:[];$records=@dns_get_record($host,DNS_A|DNS_AAAA);$ips=[];foreach(is_array($records)?$records:[] as $record){$ip=(string)($record['ip']??$record['ipv6']??'');if($ip!=='')$ips[]=$ip;}if(!$ips){$ips=@gethostbynamel($host)?:[];}if(!$ips)return [];foreach(array_unique($ips) as $ip)if(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)===false)return [];return array_values(array_unique($ips));}
function connector_host_allowed(string $host):bool{$host=strtolower(trim($host,'[] .'));if($host===''||preg_match('/[\r\n\/@?#]/',$host))return false;$allow=array_map(static fn($item)=>strtolower(trim($item,'[] .')),array_filter(array_map('trim',explode(',',(string)(getenv('CONNECTOR_HOST_ALLOWLIST')?:'')))));$private=filter_var(getenv('CONNECTOR_ALLOW_PRIVATE_NETWORK')?:'false',FILTER_VALIDATE_BOOLEAN);if($allow&&!in_array($host,$allow,true))return false;if(($host==='localhost'||str_ends_with($host,'.local'))&&!$private)return false;if($private)return true;if(!$allow)return false;return connector_public_ips($host)!==[];}
function app_setting(string $key,string $default=''):string{return (string)(getenv($key)?:$default);}
function format_number(float|int $number,int $decimals=0):string{return number_format((float)$number,$decimals,',','.');}
function format_money(float|int $number,string $currency='IDR'):string{$n=format_number((float)$number,2);return $currency==='GBP'?'£'.$n:($currency==='USD'?'$'.$n:'Rp'.$n);}
function route_path(string $page):string{return url($page);}
